create extension if not exists pgcrypto;
create table public.jurisdictions (id uuid primary key default gen_random_uuid(), state_code text not null check (state_code ~ '^[A-Z]{2}$'), name text not null, kind text not null check(kind in ('state','county','city','district','federal','other')), unique(state_code,name,kind));
create table public.agencies (id uuid primary key default gen_random_uuid(), jurisdiction_id uuid references public.jurisdictions(id), name text not null, official_url text, unique(jurisdiction_id,name));
create table public.people (id uuid primary key default gen_random_uuid(), name text not null, role_title text, affiliation text check(affiliation in ('government','flock','other')), official_profile_url text, notes text);
create table public.sources (id uuid primary key default gen_random_uuid(), url text not null unique check(url ~* '^https://'), title text not null, publisher text, published_on date, retrieved_at timestamptz not null default now(), source_type text not null default 'other', content_excerpt text, status text not null default 'pending' check(status in ('pending','verified','rejected')));
create table public.contracts (id uuid primary key default gen_random_uuid(), agency_id uuid not null references public.agencies(id), vendor text not null default 'Flock Safety' check(vendor = 'Flock Safety'), contract_number text, signed_on date, starts_on date, ends_on date, amount_usd numeric(14,2) check(amount_usd >= 0), status text not null default 'unknown' check(status in ('proposed','active','expired','terminated','unknown')), source_id uuid not null references public.sources(id), review_status text not null default 'draft' check(review_status in ('draft','reviewed','published')), summary text);
create table public.actions (id uuid primary key default gen_random_uuid(), person_id uuid references public.people(id), agency_id uuid references public.agencies(id), jurisdiction_id uuid references public.jurisdictions(id), action_type text not null check(action_type in ('vote','statement','contract_approval','contract_termination','hearing','policy_change','other')), action_date date, factual_description text not null, recorded_position text check(recorded_position in ('for','against','abstain','mixed','not_applicable','unknown')), source_id uuid not null references public.sources(id), review_status text not null default 'draft' check(review_status in ('draft','reviewed','published')));
create table public.deployments (id uuid primary key default gen_random_uuid(), agency_id uuid not null references public.agencies(id), camera_count integer check(camera_count >= 0), status text not null default 'unknown', as_of_date date, geography_label text, source_id uuid not null references public.sources(id), review_status text not null default 'draft' check(review_status in ('draft','reviewed','published')));
create table public.discovery_queue (id uuid primary key default gen_random_uuid(), url text not null unique check(url ~* '^https://'), headline text not null, publisher text, discovered_at timestamptz not null default now(), snippet text, state_hint text, status text not null default 'unreviewed' check(status in ('unreviewed','in_review','accepted','rejected')), reviewer_notes text);
create index jurisdictions_state_idx on public.jurisdictions(state_code);
create index actions_person_idx on public.actions(person_id);
create index actions_agency_idx on public.actions(agency_id);
create index contracts_agency_idx on public.contracts(agency_id);
create index discovery_queue_status_idx on public.discovery_queue(status,discovered_at desc);
create view public.published_actions with (security_invoker=true) as select a.* from public.actions a join public.sources s on s.id=a.source_id where a.review_status='published' and s.status='verified';
create view public.published_contracts with (security_invoker=true) as select c.* from public.contracts c join public.sources s on s.id=c.source_id where c.review_status='published' and s.status='verified';
create view public.published_deployments with (security_invoker=true) as select d.* from public.deployments d join public.sources s on s.id=d.source_id where d.review_status='published' and s.status='verified';
do $$ declare t text; begin foreach t in array array['jurisdictions','agencies','people','sources','contracts','actions','deployments','discovery_queue'] loop execute format('alter table public.%I enable row level security',t); execute format('revoke all on public.%I from anon, authenticated',t); end loop; end $$;
grant select on public.jurisdictions,public.agencies,public.people,public.sources,public.contracts,public.actions,public.deployments to anon,authenticated;
create policy public_jurisdictions on public.jurisdictions for select to anon,authenticated using(true);
create policy public_agencies on public.agencies for select to anon,authenticated using(true);
create policy public_people on public.people for select to anon,authenticated using(true);
create policy public_sources on public.sources for select to anon,authenticated using(status='verified');
create policy public_contracts on public.contracts for select to anon,authenticated using(review_status='published' and exists(select 1 from public.sources s where s.id=source_id and s.status='verified'));
create policy public_actions on public.actions for select to anon,authenticated using(review_status='published' and exists(select 1 from public.sources s where s.id=source_id and s.status='verified'));
create policy public_deployments on public.deployments for select to anon,authenticated using(review_status='published' and exists(select 1 from public.sources s where s.id=source_id and s.status='verified'));
revoke all on public.discovery_queue from anon,authenticated;
grant select on public.published_actions,public.published_contracts,public.published_deployments to anon,authenticated;
